@mixin subscribeIcon {
  &::before {
    display: block;
    width: 19px;
    height: 19px;
    margin: 0px auto -15px;
    content: "";
    background-image: url('../images/SubscribeIcon_Locker.svg');
    background-repeat: no-repeat;
    background-position: 0 0;
    background-size: cover;
    position: relative;
    top: -8px;
    @include breakpoint($bp-small) {
      padding-left: 5px;
      width: calc($gutter*.75);
      height: 26px;
      margin: 0 auto;
      position: absolute;
      left: 34px;
      top: 10px;
    }
  }
}

@mixin triangle-right {
  width: 0; 
  height: 0; 
  border-top: calc($gutter/2) solid transparent;
  border-bottom: calc($gutter/2) solid transparent;
  border-left: 12px solid $homepagePurple;
  position: absolute;
  top: 0px;
  right: -12px;
  z-index: 1;
}

.ama__series,
.ama__trending,
.ama__topic_terms {
  //Taxonomy specific subscribe series styling
  .salesforce-subscribe-form {
    display: inline-block;
    border: none;
    line-height: 0;
    position: relative;
    margin-top: calc($gutter * 1.25);
    @include breakpoint($bp-small max-width) {
      height: 44px;
    }
    @include subscribeIcon();
    @include breakpoint($bp-small max-width) {
      &::before {
        position: relative;
        top: -2px;
      }
    }
    .form-actions {
      margin: 0;
    }
    input.form-submit {
      border: 1px solid $glossary-purple;
      background: none;
      color: $bookmark-purple;
      @include type($myriad-pro, $font-weight-regular);
      margin-bottom: 0;
      padding: 15px 0 0 0;
      line-height: 1.5em;
      font-size: 16px;
      @include breakpoint($bp-small max-width) {
        width: 87px;
        height: 44px;
        font-size: calc($gutter/2);
        line-height: 2;
        top: -10px;
      }
      @include breakpoint($bp-small) {
        min-width: 180px;
        max-width: 180px;
        max-height: 46px;
        padding: 9px 0 8px 25px;
        margin-bottom: 5px;
      }
    }
    &:hover {
      &::before {
        background-image: url('../images/SubscribeHoverIcon_Locker.svg');
      }
      input.form-submit {
        text-decoration: underline;
      }
    }
    + .flag {
      display: inline-block;
      margin-top: 1px;
    }
  }

  //Taxonomy specific subscribed series styling
  .subscribe-series {
    display: inline-block;
    border: 1px solid $glossary-purple;
    background: none;
    color: $bookmark-purple;
    margin-bottom: 0;
    text-align: center;
    text-decoration: none;
    padding: 15px 0 0 0;
    position: relative;
    top: 0;
    @include breakpoint($bp-small max-width) {
      width: 87px;
      height: 44px;
      font-size: calc($gutter/2);
      line-height: 2;
      top: -8px;
    }
    @include breakpoint($bp-small) {
      min-width: 180px;
      max-width: 180px;
      max-height: 46px;
      padding: calc($gutter/4) 0 8px 25px;
      margin-bottom: 5px;
      margin-top: 35px;
    }
    + .flag {
      display: inline-block;
      margin-top: 0px;
      @include breakpoint($bp-small max-width) {
        position: relative;
        top: -10px;
      }
    }
    &:hover {
      text-decoration: underline;
      &::before {
        background-image: url('../images/SubscribeHoverIcon_Locker.svg');
      }
    }
    @include subscribeIcon();
    @include breakpoint($bp-small max-width) {
      position: relative;
      top: -8px;
    }
    &.subscribed {
      &::before {
        background-image: url('../images/SubscribedIcon_Locker.svg');
        @include breakpoint($bp-small) {
          left: $gutter;
        }
      }
    }
  }
}

.news-subscribe-wrapper {
  max-height: 36px;
  @include breakpoint($bp-small) {
    justify-content: flex-end;
  }
  .sub-title {
      margin-right: calc($gutter/2);
      display: flex;
      align-items: center;
      width: 100%;

      @include breakpoint($bp-small) {
        @include breakpoint(700px max-width) {
          display: none;
        }
      }

      @include breakpoint($bp-med) {
        display: flex;
        width: 80%;
      }

    a {
      font-size: calc($gutter/2);
      text-align: right;
      font-weight: $font-weight-bold;
      color: $homepagePurple;
      text-transform: uppercase;
      text-decoration: none;
      line-height: 150%; /* 21px */
      letter-spacing: 1.12px;
      max-height: 36px;

      &:focus-visible {
        outline: 2px solid $tab-focus-blue;
        outline-offset: 5px;
      }

      &:hover {
        text-decoration: underline;
      }
    }
  }
  span {
    &.icon--subscribe-news {
      display: flex;
      &::after {
        content: " ";
        background-repeat: no-repeat;
        background-position: 0 0;
        background-size: cover;
        left: 0;
        margin-right: 6px;
        display: block;
        background-position: center;
        height: 24px;
        width: 16px;
        background-image: url("../icons/svg/social-share-icons/v1-icon-subscribe.svg");
      }
      &.ama__button--news-subscribe-subscribed {
        &::after {
          background-image: url("../icons/svg/social-share-icons/v1-icon-subscribed.svg");
        }
      }
    }
  }
}

a.subscribe-series {
  display: block;
  min-height: $gutter;
  top: -30px;
}

.series-tag + .subscribe-series,
.series-tag + .salesforce-subscribe-form input.form-submit {
  position: relative;
  text-decoration: none;
  @include type($myriad-pro, $font-weight-semibold);
  text-align: left;
  text-transform: uppercase;
  font-size: calc($gutter/2);
  line-height: 2;
  width: 182px;
  color: $white;
  background: $homepagePurple;
  padding-left: 20px;
  @include breakpoint($bp-small) {
    width: 168px;
    padding-left: 8px;
  }
  &:after {
    display: inline-block;
    content: '';
    width: 18px;
    height: 18px;
    background: url(../icons/svg/subscribe-hover.svg) no-repeat 0 0;
    background-size: contain;
    position: relative;
    top: 3px;
    left: 8px;
    z-index: 1;
  }
  &:hover {
    cursor: pointer;
    background: $purple;
    input.form-submit {
      cursor: pointer;
      background-color: $purple;
    }
    .triangle-right {
      border-left: 12px solid $purple;
    }
  }

  .triangle-right {
    @include triangle-right();
  }

  &.subscribed {
    color: $purple;
    background: $white;
    border: 1px solid $purple;
    text-align: center !important;
    padding: 0;
    &:after {
      content: none;
    }

    .triangle-right {
      display: none;
    }
  }
}

//Subscribe to series button styling on articles
.series-tag + .subscribe-series,
.series-tag + .salesforce-subscribe-form {
  width: 168px;
  position: relative;
  top: 0;
  margin-top: $gutter;
  .triangle-right {
    @include triangle-right();
  }
  &:hover {
    .triangle-right {
      border-left: 12px solid $purple;
    }
  }

  input.form-submit {
    margin: 0;
    padding-top: 0;
    padding-bottom: 0;
    border: none;
  }

  .form-actions {
    margin: 0;
    padding-top: 0;
    padding-bottom: 0;
    border: none;
    &:after {
      display: inline-block;
      content: '';
      width: 18px;
      height: 18px;
      background: url(../icons/svg/subscribe-hover.svg) no-repeat 0 0;
      background-size: contain;
      position: absolute;
      right: 5px;
      top: 5px;
      z-index: 1;
    }
  }
}

.series-tag + .salesforce-subscribe-form {
  .triangle-right {
    top: 2px;
  }
}